import sys

s = sys.stdin.read().split()[0]
n = len(s)
cnt = 0
for i in range(n):
    for j in range(i + 1, n):
        if s[j] == s[i]:
            continue
        for k in range(j + 1, n):
            if s[k] != s[j]:
                cnt += 1
print(cnt)

